style.css:
css
/* dreamy ILLIT Roblox */
:root {
  --my-pink: #ffd6e8;
  --my-lavender: #e6d9ff;
  --my-white: #fff8fc;
}

/* dreamy background */
body {
  background: linear-gradient(
    135deg,
    var(--my-pink),
    var(--my-lavender),
    var(--my-white)
  ) !important;
  background-attachment: fixed !important;
}

/* soft text */
h1, h2, h3 {
  color: #b77ba9 !important;
}

/* cute links */
a {
  color: #d77eae !important;
}

/* rounded images */
img {
  border-radius: 16px !important;
}
